const rules = $('Get Active Rules').all().map(i => i.json);
const logs = $('Get Fire Counts').all().map(i => i.json);
const now = Date.now();

const countByRule = {};
const countByRule24 = {};
const lastFiredByRule = {};
for (const log of logs) {
  if (!log.rule_id) continue;
  const t = new Date(log.created_at + (log.created_at.endsWith('Z') ? '' : 'Z')).getTime();
  if (now - t < 7 * 86400000) {
    countByRule[log.rule_id] = (countByRule[log.rule_id] || 0) + 1;
    if (now - t < 86400000) {
      countByRule24[log.rule_id] = (countByRule24[log.rule_id] || 0) + 1;
    }
    if (!lastFiredByRule[log.rule_id] || t > lastFiredByRule[log.rule_id]) {
      lastFiredByRule[log.rule_id] = t;
    }
  }
}

const formatConditions = (rule) => {
  const conds = rule.conditions || [];
  const combinator = (rule.combinator || 'AND').toUpperCase();
  return conds.map(c => {
    const lb = c.lookback === 'today' ? '' : ` (${String(c.lookback).replace('last_', '')})`;
    const op = { gt: '>', lt: '<', gte: '≥', lte: '≤', eq: '=' }[c.operator] || c.operator;
    return `${c.metric}${lb} ${op} ${c.value}`;
  }).join(` ${combinator} `);
};

const nowIso = new Date().toISOString();
return rules.map(r => ({
  json: {
    fields: {
      'ID': r.id,
      'Name': r.name || '',
      'Status': r.is_active ? 'Active' : 'Paused',
      'Mode': r.is_dry_run ? 'Dry Run' : 'Live',
      'Scope': r.scope || '',
      'Action': r.action || '',
      'Action Params': r.action_params ? JSON.stringify(r.action_params) : '',
      'Conditions': formatConditions(r),
      'Combinator': (r.combinator || 'AND').toUpperCase(),
      'Cooldown (hrs)': r.cooldown_hours || 0,
      'Alert Level': r.alert_level || 'warning',
      'Last Fired': lastFiredByRule[r.id] ? new Date(lastFiredByRule[r.id]).toISOString() : null,
      'Fires (24h)': countByRule24[r.id] || 0,
      'Fires (7d)': countByRule[r.id] || 0,
      'Synced At': nowIso
    }
  }
}));

const all = $input.all().map(i => i.json);
const chunks = [];
for (let i = 0; i < all.length; i += 10) {
  chunks.push({ json: { records: all.slice(i, i + 10) } });
}
return chunks;
